import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Kernel 日报 2026-11-27","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/27.md","filePath":"notes/kernel-digest/2026/11/27.md"}'),n={name:"notes/kernel-digest/2026/11/27.md"};function l(i,e,s,c,d,f){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-27" tabindex="-1">Kernel 日报 2026-11-27 <a class="header-anchor" href="#kernel-日报-2026-11-27" aria-label="Permalink to &quot;Kernel 日报 2026-11-27&quot;">​</a></h1><blockquote><p>生成时间：2026-11-27T01:44:05Z｜共 36 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-27 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_0e89198a0bf1-·-patch-net-v2-0-4-net-skbuff-limit-pagecache-folio-refcount" tabindex="-1"><code>0e89198a0bf1</code> · <a href="https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-0-a6f600a5634a@kernel.org/" target="_blank" rel="noreferrer">[PATCH net v2 0/4] net: skbuff: limit pagecache folio refcount</a> <a class="header-anchor" href="#_0e89198a0bf1-·-patch-net-v2-0-4-net-skbuff-limit-pagecache-folio-refcount" aria-label="Permalink to &quot;`0e89198a0bf1` · [[PATCH net v2 0/4] net: skbuff: limit pagecache folio refcount](https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-0-a6f600a5634a@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>这是 folio refcount 溢出修复系列的 v2 cover letter，包含剩余需经 net tree 合入的修复。该系列基于 Linus 树中已合入的 mm 前置补丁 c6c9a4c1c9a16（mm: limit pagecache folio refcount when splicing into pipes），后者为 try_get_page() 增加了引用上限检查。溢出会导致引用计数变负或回绕，引发严重问题。</p><blockquote><p><strong>学习价值</strong>：通过 cover letter 可学习大型跨子系统修复系列的组织方式和补丁依赖管理实践。</p></blockquote><h3 id="ea57086ca586-·-patch-v2-nf-0-5-netfilter-pin-file-with-get-file-active-before-reading-f-cred" tabindex="-1"><code>ea57086ca586</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-1-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 0/5] netfilter: pin file with get_file_active before reading f_cred</a> <a class="header-anchor" href="#ea57086ca586-·-patch-v2-nf-0-5-netfilter-pin-file-with-get-file-active-before-reading-f-cred" aria-label="Permalink to &quot;`ea57086ca586` · [[PATCH v2 nf 0/5] netfilter: pin file with get_file_active before reading f_cred](https://lore.kernel.org/all/20261127001637.1026589-1-tristmd@gmail.com/)&quot;">​</a></h3><p><em>Tristan Madani (<a href="mailto:tristmd@gmail.com" target="_blank" rel="noreferrer">tristmd@gmail.com</a>)｜netdev｜网络</em></p><p>本系列修复 netfilter 中五处调用点：它们在 RCU 下通过 sk-&gt;sk_socket-&gt;file 链读取 f_cred 却未固定 file 引用。自 commit 0ede61d8589c 将 file slab 转换为 SLAB_TYPESAFE_BY_RCU 后，file 对象可在宽限期内被释放并重新分配，导致读到复用对象的过期凭据。系列统一采用 get_file_active() 固定、fput() 释放的模式，与已合入的 cls_flow 修复（commit 59cf9e6f48e5a）保持一致。</p><blockquote><p><strong>学习价值</strong>：作为 cover letter，清晰呈现了一个核心 slab 语义变更如何在多个子系统中引发连锁修复，是学习跨子系统回归分析的范本。</p></blockquote><h3 id="_7e2a8993dd8a-·-it-looks-like-ai-agent-skills-will-be-submitted-for-linux-7-5" tabindex="-1"><code>7e2a8993dd8a</code> · <a href="https://www.phoronix.com/news/Linux-AI-Agent-Skills-Ready" target="_blank" rel="noreferrer">It Looks Like AI Agent Skills Will Be Submitted For Linux 7.5</a> <a class="header-anchor" href="#_7e2a8993dd8a-·-it-looks-like-ai-agent-skills-will-be-submitted-for-linux-7-5" aria-label="Permalink to &quot;`7e2a8993dd8a` · [It Looks Like AI Agent Skills Will Be Submitted For Linux 7.5](https://www.phoronix.com/news/Linux-AI-Agent-Skills-Ready)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>在即将于 12 月底开启的 Linux 7.5 merge window 中，社区计划提交 AI agent skills 相关内容，即在内核树内添加文档，用于指导 AI agent 理解和参与内核开发流程。这标志着 AI 辅助开发正被正式纳入内核工作流。</p><blockquote><p><strong>学习价值</strong>：了解内核社区如何主动拥抱 AI 辅助开发，是观察内核开发流程演进的重要窗口。</p></blockquote><h3 id="_2fc70ff2b0ba-·-amid-all-the-ai-generated-patches-bug-reports-linux-gains-another-network-maintainer" tabindex="-1"><code>2fc70ff2b0ba</code> · <a href="https://www.phoronix.com/news/Linux-Another-Net-Maintainer" target="_blank" rel="noreferrer">Amid All The AI Generated Patches &amp; Bug Reports, Linux Gains Another Network Maintainer</a> <a class="header-anchor" href="#_2fc70ff2b0ba-·-amid-all-the-ai-generated-patches-bug-reports-linux-gains-another-network-maintainer" aria-label="Permalink to &quot;`2fc70ff2b0ba` · [Amid All The AI Generated Patches &amp; Bug Reports, Linux Gains Another Network Maintainer](https://www.phoronix.com/news/Linux-Another-Net-Maintainer)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>由于过去一年大量 AI/LLM 生成的 bug report 和 patch 让 Linux networking 维护者不堪重负，甚至导致部分修复被推迟到下个版本、部分老旧网络代码被直接移除。作为应对，又一位开发者被提升为 networking 子系统的额外 maintainer。</p><blockquote><p><strong>学习价值</strong>：展示了 AI 生成内容对上游内核维护生态的实际冲击，以及社区通过扩充 maintainer 队伍的应对策略。</p></blockquote><h3 id="a923515486ad-·-patch-net-next-rxrpc-reject-unsecured-calls-to-userspace-services-with-a-minimum-level" tabindex="-1"><code>a923515486ad</code> · <a href="https://lore.kernel.org/all/20261126224137.55862-1-bugs@stellman-greene.com/" target="_blank" rel="noreferrer">[PATCH net-next] rxrpc: Reject unsecured calls to userspace services with a minimum level</a> <a class="header-anchor" href="#a923515486ad-·-patch-net-next-rxrpc-reject-unsecured-calls-to-userspace-services-with-a-minimum-level" aria-label="Permalink to &quot;`a923515486ad` · [[PATCH net-next] rxrpc: Reject unsecured calls to userspace services with a minimum level](https://lore.kernel.org/all/20261126224137.55862-1-bugs@stellman-greene.com/)&quot;">​</a></h3><p><em>Andrew Stellman (<a href="mailto:bugs@stellman-greene.com" target="_blank" rel="noreferrer">bugs@stellman-greene.com</a>)｜netdev｜网络</em></p><p>rxrpc 的 rxrpc_get_incoming_security() 未检查 rx-&gt;min_sec_level，导致用户态服务 socket 即使设置了高于 RXRPC_SECURITY_PLAIN 的最低安全级别，仍会接受安全索引为 RXRPC_SECURITY_NONE 的未加密呼入。补丁在此情况下拒绝未安全呼入，内核 socket（如 kAFS、rxperf）因已设置 RXRPC_SECURITY_ENCRYPT 而不受影响。</p><blockquote><p><strong>学习价值</strong>：展示了协议安全级别检查的边界情况：安全策略校验遗漏在哪个环节引入，以及如何兼顾内核内部使用者的兼容性。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（10 条）</li><li><strong>网络</strong>（8 条）</li><li><strong>文件系统与存储</strong>（2 条）</li><li><strong>Rust in Linux</strong>（10 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（4 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="b53427889e90-·-akpm-mm-mm-new-build-success-3d27e49eb905a5119e78fbe3d3890f376d15c728" tabindex="-1"><code>b53427889e90</code> · <a href="https://lore.kernel.org/all/20261127061255.sXY6esvU-lkp@intel.com/" target="_blank" rel="noreferrer">[akpm-mm:mm-new] BUILD SUCCESS 3d27e49eb905a5119e78fbe3d3890f376d15c728</a> <a class="header-anchor" href="#b53427889e90-·-akpm-mm-mm-new-build-success-3d27e49eb905a5119e78fbe3d3890f376d15c728" aria-label="Permalink to &quot;`b53427889e90` · [[akpm-mm:mm-new] BUILD SUCCESS 3d27e49eb905a5119e78fbe3d3890f376d15c728](https://lore.kernel.org/all/20261127061255.sXY6esvU-lkp@intel.com/)&quot;">​</a></h3><p><em>kernel test robot (<a href="mailto:lkp@intel.com" target="_blank" rel="noreferrer">lkp@intel.com</a>)｜linux-mm</em></p><p>kernel test robot 报告 akpm/mm.git mm-new 分支在 commit 3d27e49e（tools/mm: page-types: flush pending idle bitmap bits after walking）上构建成功，共测试 358 个配置，涵盖 alpha 架构下多种 gcc 版本的 allnoconfig、allyesconfig、defconfig 和 randconfig。</p><blockquote><p><strong>学习价值</strong>：展示了 0-Day/LKP 自动化测试体系如何覆盖 Andrew Morton 的 mm 树，可了解内核 CI 的运作方式。</p></blockquote><h3 id="_5ff230a8bbd1-·-patch-net-v2-3-4-net-skbuff-limit-folio-refcount-when-splicing-pages-into-skbs" tabindex="-1"><code>5ff230a8bbd1</code> · <a href="https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-3-a6f600a5634a@kernel.org/" target="_blank" rel="noreferrer">[PATCH net v2 3/4] net: skbuff: limit folio refcount when splicing pages into skbs</a> <a class="header-anchor" href="#_5ff230a8bbd1-·-patch-net-v2-3-4-net-skbuff-limit-folio-refcount-when-splicing-pages-into-skbs" aria-label="Permalink to &quot;`5ff230a8bbd1` · [[PATCH net v2 3/4] net: skbuff: limit folio refcount when splicing pages into skbs](https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-3-a6f600a5634a@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>多个网络特性通过 MSG_SPLICE_PAGES 向 skb 添加页面，skb_append_pagefrags() 会为每个 fragment 获取 page 引用；虽然从 pipe splice 进来的页面已有检查，但 sunrpc 等内核内用户会直接传入 pagecache 页面，仍可能超出 folio refcount 限制。修复是在 skb_append_pagefrags() 中使用 try_get_page()，失败时返回 -EFAULT 而非 -EMSGSIZE。</p><blockquote><p><strong>学习价值</strong>：与 id 9 构成系列补丁，完整展示了 refcount 限制问题在 skb 路径上的修复思路及错误码选择的考量。</p></blockquote><h3 id="ee8d0975d14c-·-patch-net-v2-2-4-net-skbuff-limit-folio-refcount-when-rearranging-skb-frags" tabindex="-1"><code>ee8d0975d14c</code> · <a href="https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-2-a6f600a5634a@kernel.org/" target="_blank" rel="noreferrer">[PATCH net v2 2/4] net: skbuff: limit folio refcount when rearranging skb frags</a> <a class="header-anchor" href="#ee8d0975d14c-·-patch-net-v2-2-4-net-skbuff-limit-folio-refcount-when-rearranging-skb-frags" aria-label="Permalink to &quot;`ee8d0975d14c` · [[PATCH net v2 2/4] net: skbuff: limit folio refcount when rearranging skb frags](https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-2-a6f600a5634a@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>该补丁处理 skb frags 重排时的 folio refcount 溢出问题。软件 GSO 分段、TCP 接收合并、SACK shifting 和 MTU probing 等网络特性会对 frag page 额外增加引用，导致 folio 引用计数可能超过上限。补丁在 skb_segment() 等路径中使用 skb_frag_try_ref() 和 skb_frags_try_ref() 来限制引用计数。</p><blockquote><p><strong>学习价值</strong>：展示了网络与内存管理子系统的交叉问题，是理解 folio refcount 溢出风险和 try_get_page() 防御机制的绝佳案例。</p></blockquote><h3 id="_9b6381fa94b4-·-patch-net-v2-1-4-net-skbuff-limit-folio-refcount-when-copying-skb-frag-references" tabindex="-1"><code>9b6381fa94b4</code> · <a href="https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-1-a6f600a5634a@kernel.org/" target="_blank" rel="noreferrer">[PATCH net v2 1/4] net: skbuff: limit folio refcount when copying skb frag references</a> <a class="header-anchor" href="#_9b6381fa94b4-·-patch-net-v2-1-4-net-skbuff-limit-folio-refcount-when-copying-skb-frag-references" aria-label="Permalink to &quot;`9b6381fa94b4` · [[PATCH net v2 1/4] net: skbuff: limit folio refcount when copying skb frag references](https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-1-a6f600a5634a@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>该补丁针对复制 skb frag 引用时可能导致的 folio refcount 溢出问题，涉及 unshare 克隆 skb（AF_PACKET trim）、复制 skb（nft dup）以及构建 NFQUEUE 消息等场景。补丁引入基于 try_get_page() 的 skb_frag_try_ref() 和 skb_frags_try_ref()，并在 pskb_expand_head() 等路径中使用。</p><blockquote><p><strong>学习价值</strong>：帮助学习者理解引用计数安全获取模式（try-get）在跨子系统资源管理中的重要性。</p></blockquote><h3 id="_0e89198a0bf1-·-patch-net-v2-0-4-net-skbuff-limit-pagecache-folio-refcount-1" tabindex="-1"><code>0e89198a0bf1</code> · <a href="https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-0-a6f600a5634a@kernel.org/" target="_blank" rel="noreferrer">[PATCH net v2 0/4] net: skbuff: limit pagecache folio refcount</a> <a class="header-anchor" href="#_0e89198a0bf1-·-patch-net-v2-0-4-net-skbuff-limit-pagecache-folio-refcount-1" aria-label="Permalink to &quot;`0e89198a0bf1` · [[PATCH net v2 0/4] net: skbuff: limit pagecache folio refcount](https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-0-a6f600a5634a@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>这是 folio refcount 溢出修复系列的 v2 cover letter，包含剩余需经 net tree 合入的修复。该系列基于 Linus 树中已合入的 mm 前置补丁 c6c9a4c1c9a16（mm: limit pagecache folio refcount when splicing into pipes），后者为 try_get_page() 增加了引用上限检查。溢出会导致引用计数变负或回绕，引发严重问题。</p><blockquote><p><strong>学习价值</strong>：通过 cover letter 可学习大型跨子系统修复系列的组织方式和补丁依赖管理实践。</p></blockquote><h3 id="_73775cefda14-·-rfc-patch-4-4-mm-damon-sysfs-remove-damon-sysfs-cmd-strs" tabindex="-1"><code>73775cefda14</code> · <a href="https://lore.kernel.org/all/20261126210619.97634-5-sj@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH 4/4] mm/damon/sysfs: remove damon_sysfs_cmd_strs</a> <a class="header-anchor" href="#_73775cefda14-·-rfc-patch-4-4-mm-damon-sysfs-remove-damon-sysfs-cmd-strs" aria-label="Permalink to &quot;`73775cefda14` · [[RFC PATCH 4/4] mm/damon/sysfs: remove damon_sysfs_cmd_strs](https://lore.kernel.org/all/20261126210619.97634-5-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>该补丁移除了 mm/damon/sysfs.c 中实际未被使用的 damon_sysfs_cmd_strs 数组，是 DAMON sysfs 接口状态输入匹配重构系列的收尾清理。删除后由新的 damon_sysfs_cmd_names 结构替代原有功能。</p><blockquote><p><strong>学习价值</strong>：展示了内核代码重构中“先替换、后删除”的渐进式清理流程。</p></blockquote><h3 id="be9797e7d33c-·-rfc-patch-3-4-mm-damon-sysfs-use-damon-sysfs-cmd-names-in-state-show" tabindex="-1"><code>be9797e7d33c</code> · <a href="https://lore.kernel.org/all/20261126210619.97634-4-sj@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH 3/4] mm/damon/sysfs: use damon_sysfs_cmd_names in state_show()</a> <a class="header-anchor" href="#be9797e7d33c-·-rfc-patch-3-4-mm-damon-sysfs-use-damon-sysfs-cmd-names-in-state-show" aria-label="Permalink to &quot;`be9797e7d33c` · [[RFC PATCH 3/4] mm/damon/sysfs: use damon_sysfs_cmd_names in state_show()](https://lore.kernel.org/all/20261126210619.97634-4-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>该补丁将 DAMON sysfs 接口中 kdamond state 文件的读取处理函数 state_show() 改为使用新的 damon_sysfs_cmd_names 数组，替代原有的 damon_sysfs_cmd_strs。属于状态输入匹配重构系列的第三步。</p><blockquote><p><strong>学习价值</strong>：可学习 sysfs 属性 show/store 回调的实现模式以及接口代码的重构方法。</p></blockquote><h3 id="ce15e011a5ba-·-rfc-patch-1-4-mm-damon-sysfs-define-damon-sysfs-cmd-name-type-and-array" tabindex="-1"><code>ce15e011a5ba</code> · <a href="https://lore.kernel.org/all/20261126210619.97634-2-sj@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH 1/4] mm/damon/sysfs: define damon_sysfs_cmd_name type and array</a> <a class="header-anchor" href="#ce15e011a5ba-·-rfc-patch-1-4-mm-damon-sysfs-define-damon-sysfs-cmd-name-type-and-array" aria-label="Permalink to &quot;`ce15e011a5ba` · [[RFC PATCH 1/4] mm/damon/sysfs: define damon_sysfs_cmd_name type and array](https://lore.kernel.org/all/20261126210619.97634-2-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>该补丁为 DAMON sysfs 接口定义了新的 struct damon_sysfs_cmd_name 类型及对应数组，用于 kdamond state 文件的用户输入处理。该结构显式描述了每个用户输入对应的 kdamond 命令，避免依赖字符串数组与 enum 顺序隐式匹配的脆弱设计。</p><blockquote><p><strong>学习价值</strong>：体现了用显式数据结构替代隐式顺序约定来提升代码健壮性的设计思想。</p></blockquote><h3 id="_26c36172635b-·-rfc-patch-2-4-mm-damon-sysfs-use-damon-sysfs-cmd-names-in-state-store" tabindex="-1"><code>26c36172635b</code> · <a href="https://lore.kernel.org/all/20261126210619.97634-3-sj@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH 2/4] mm/damon/sysfs: use damon_sysfs_cmd_names in state_store()</a> <a class="header-anchor" href="#_26c36172635b-·-rfc-patch-2-4-mm-damon-sysfs-use-damon-sysfs-cmd-names-in-state-store" aria-label="Permalink to &quot;`26c36172635b` · [[RFC PATCH 2/4] mm/damon/sysfs: use damon_sysfs_cmd_names in state_store()](https://lore.kernel.org/all/20261126210619.97634-3-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>该补丁将 DAMON sysfs 接口中 kdamond state 文件的写入处理函数 state_store() 改为使用新的 damon_sysfs_cmd_names 数组进行输入匹配，替代原有的 damon_sysfs_cmd_strs。属于状态输入匹配重构系列的第二步。</p><blockquote><p><strong>学习价值</strong>：结合系列其他补丁可完整学习一次小型内核重构从设计到落地的全过程。</p></blockquote><h3 id="_9514b3ee2607-·-rfc-patch-0-4-mm-damon-sysfs-refactor-state-input-matching" tabindex="-1"><code>9514b3ee2607</code> · <a href="https://lore.kernel.org/all/20261126210619.97634-1-sj@kernel.org/" target="_blank" rel="noreferrer">[RFC PATCH 0/4] mm/damon/sysfs: refactor state input matching</a> <a class="header-anchor" href="#_9514b3ee2607-·-rfc-patch-0-4-mm-damon-sysfs-refactor-state-input-matching" aria-label="Permalink to &quot;`9514b3ee2607` · [[RFC PATCH 0/4] mm/damon/sysfs: refactor state input matching](https://lore.kernel.org/all/20261126210619.97634-1-sj@kernel.org/)&quot;">​</a></h3><p><em>SJ Park (<a href="mailto:sj@kernel.org" target="_blank" rel="noreferrer">sj@kernel.org</a>)｜linux-mm</em></p><p>这是 DAMON sysfs 接口状态输入匹配重构系列的 cover letter。原实现中 damon_sysfs_cmd_strs 字符串数组的顺序必须与 enum damon_sysfs_cmd 保持一致，容易出错。系列改为使用专用 struct 数组进行匹配：补丁 1 定义新结构，补丁 2、3 更新 state 文件的读写处理，补丁 4 删除旧数组。</p><blockquote><p><strong>学习价值</strong>：是学习内核补丁系列组织结构和“消除隐式耦合”重构原则的好材料。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="d963c5ec468c-·-patch-net-v2-4-4-net-skbuff-limit-folio-refcount-when-splicing-from-sockets" tabindex="-1"><code>d963c5ec468c</code> · <a href="https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-4-a6f600a5634a@kernel.org/" target="_blank" rel="noreferrer">[PATCH net v2 4/4] net: skbuff: limit folio refcount when splicing from sockets</a> <a class="header-anchor" href="#d963c5ec468c-·-patch-net-v2-4-4-net-skbuff-limit-folio-refcount-when-splicing-from-sockets" aria-label="Permalink to &quot;`d963c5ec468c` · [[PATCH net v2 4/4] net: skbuff: limit folio refcount when splicing from sockets](https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-4-a6f600a5634a@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>TCP、AF_UNIX、KCM、kTLS 等均支持将 socket 数据 splice 到 pipe，spd_fill_page() 会为每个 fragment 额外获取 page 引用，而 skb 在完全消费前仍持有自己的引用，这可能导致 folio refcount 超限（大 pagecache folio 下更易触发）。修复方案是在 spd_fill_page() 中改用 try_get_page()，失败时以 -EFAULT 终止 splice。</p><blockquote><p><strong>学习价值</strong>：深入讲解 folio refcount 溢出问题及 try_get_page() 的防御性用法，是理解 page 引用计数与网络 splice 路径交互的绝佳案例。</p></blockquote><h3 id="a23029a7b249-·-patch-v2-nf-5-5-netfilter-nf-log-syslog-pin-file-with-get-file-active-before-reading-f-cred" tabindex="-1"><code>a23029a7b249</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-6-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 5/5] netfilter: nf_log_syslog: pin file with get_file_active before reading f_cred</a> <a class="header-anchor" href="#a23029a7b249-·-patch-v2-nf-5-5-netfilter-nf-log-syslog-pin-file-with-get-file-active-before-reading-f-cred" aria-label="Permalink to &quot;`a23029a7b249` · [[PATCH v2 nf 5/5] netfilter: nf_log_syslog: pin file with get_file_active before reading f_cred](https://lore.kernel.org/all/20261127001637.1026589-6-tristmd@gmail.com/)&quot;">​</a></h3><p><em>Tristan Madani (<a href="mailto:tristmd@gmail.com" target="_blank" rel="noreferrer">tristmd@gmail.com</a>)｜netdev</em></p><p>该补丁修复 netfilter 的 nf_log_syslog 中 nf_log_dump_sk_uid_gid() 在未持有 file 引用的情况下读取 sk-&gt;sk_socket-&gt;file-&gt;f_cred 的竞态问题。由于 file slab 使用 SLAB_TYPESAFE_BY_RCU，并发 close() 可能释放并回收 file 对象，导致读到过期凭据。修复方式是在访问前用 get_file_active() 固定文件，之后 fput() 释放。</p><blockquote><p><strong>学习价值</strong>：深入展示了 SLAB_TYPESAFE_BY_RCU 语义下的 use-after-free 风险及 get_file_active() 的正确使用方式。</p></blockquote><h3 id="af6d99b7b42f-·-patch-v2-nf-4-5-netfilter-nfnetlink-queue-pin-file-with-get-file-active-before-reading-f-cred" tabindex="-1"><code>af6d99b7b42f</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-5-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 4/5] netfilter: nfnetlink_queue: pin file with get_file_active before reading f_cred</a> <a class="header-anchor" href="#af6d99b7b42f-·-patch-v2-nf-4-5-netfilter-nfnetlink-queue-pin-file-with-get-file-active-before-reading-f-cred" aria-label="Permalink to &quot;`af6d99b7b42f` · [[PATCH v2 nf 4/5] netfilter: nfnetlink_queue: pin file with get_file_active before reading f_cred](https://lore.kernel.org/all/20261127001637.1026589-5-tristmd@gmail.com/)&quot;">​</a></h3><p><em>Tristan Madani (<a href="mailto:tristmd@gmail.com" target="_blank" rel="noreferrer">tristmd@gmail.com</a>)｜netdev</em></p><p>该补丁修复 netfilter 的 nfnetlink_queue 中 nfqnl_put_sk_uidgid() 在未持有 file 引用时读取 f_cred 的竞态问题，与同系列其他补丁类似：file slab 的 SLAB_TYPESAFE_BY_RCU 特性使并发 close() 可能导致读到过期凭据。修复方式为用 get_file_active() 固定文件后再访问凭据，并以 fput() 释放。</p><blockquote><p><strong>学习价值</strong>：与同系列补丁一起展示了系统性排查同类竞态漏洞的方法论，对学习 RCU 与引用计数交互很有价值。</p></blockquote><h3 id="_82c63526284d-·-patch-v2-nf-3-5-netfilter-nfnetlink-log-pin-file-with-get-file-active-before-reading-f-cred" tabindex="-1"><code>82c63526284d</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-4-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 3/5] netfilter: nfnetlink_log: pin file with get_file_active before reading f_cred</a> <a class="header-anchor" href="#_82c63526284d-·-patch-v2-nf-3-5-netfilter-nfnetlink-log-pin-file-with-get-file-active-before-reading-f-cred" aria-label="Permalink to &quot;`82c63526284d` · [[PATCH v2 nf 3/5] netfilter: nfnetlink_log: pin file with get_file_active before reading f_cred](https://lore.kernel.org/all/20261127001637.1026589-4-tristmd@gmail.com/)&quot;">​</a></h3><p><em>Tristan Madani (<a href="mailto:tristmd@gmail.com" target="_blank" rel="noreferrer">tristmd@gmail.com</a>)｜netdev</em></p><p>netfilter 的 nfnetlink_log 子系统中，__build_packet_message() 在未持有 file 引用的情况下读取 sk-&gt;sk_socket-&gt;file-&gt;f_cred。由于 file slab 已改为 SLAB_TYPESAFE_BY_RCU，并发的 close() 可能在 RCU 宽限期内释放并复用 file 对象，导致读到过期凭据。补丁在访问前用 get_file_active() 固定 file，之后用 fput() 释放。</p><blockquote><p><strong>学习价值</strong>：这是理解 SLAB_TYPESAFE_BY_RCU 语义及其对 RCU 读端代码影响的绝佳案例，展示了引用固定（pinning）的正确模式。</p></blockquote><h3 id="c9936f006dc4-·-patch-v2-nf-2-5-netfilter-nft-meta-pin-file-with-get-file-active-before-reading-f-cred" tabindex="-1"><code>c9936f006dc4</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-3-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 2/5] netfilter: nft_meta: pin file with get_file_active before reading f_cred</a> <a class="header-anchor" href="#c9936f006dc4-·-patch-v2-nf-2-5-netfilter-nft-meta-pin-file-with-get-file-active-before-reading-f-cred" aria-label="Permalink to &quot;`c9936f006dc4` · [[PATCH v2 nf 2/5] netfilter: nft_meta: pin file with get_file_active before reading f_cred](https://lore.kernel.org/all/20261127001637.1026589-3-tristmd@gmail.com/)&quot;">​</a></h3><p><em>Tristan Madani (<a href="mailto:tristmd@gmail.com" target="_blank" rel="noreferrer">tristmd@gmail.com</a>)｜netdev</em></p><p>netfilter 的 nft_meta 子系统中，nft_meta_get_eval_skugid() 在 RCU 读临界区内未经固定引用直接读取 file-&gt;f_cred，存在读到被复用 file 对象中过期凭据的风险。修复方式是在读取前调用 get_file_active() 固定 file，读取后 fput() 释放。</p><blockquote><p><strong>学习价值</strong>：与系列其他补丁一起，展示了同一类 SLAB_TYPESAFE_BY_RCU 引用生命周期 bug 在多个调用点的系统性排查与修复方法。</p></blockquote><h3 id="da1ccd5ea6a3-·-patch-v2-nf-1-5-netfilter-xt-owner-pin-file-with-get-file-active-before-reading-f-cred" tabindex="-1"><code>da1ccd5ea6a3</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-2-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 1/5] netfilter: xt_owner: pin file with get_file_active before reading f_cred</a> <a class="header-anchor" href="#da1ccd5ea6a3-·-patch-v2-nf-1-5-netfilter-xt-owner-pin-file-with-get-file-active-before-reading-f-cred" aria-label="Permalink to &quot;`da1ccd5ea6a3` · [[PATCH v2 nf 1/5] netfilter: xt_owner: pin file with get_file_active before reading f_cred](https://lore.kernel.org/all/20261127001637.1026589-2-tristmd@gmail.com/)&quot;">​</a></h3><p><em>Tristan Madani (<a href="mailto:tristmd@gmail.com" target="_blank" rel="noreferrer">tristmd@gmail.com</a>)｜netdev</em></p><p>netfilter 的 xt_owner 匹配模块中，owner_mt() 通过 sk-&gt;sk_socket-&gt;file 链读取 f_cred 时未固定 file 引用，可能因 file 对象被回收复用而读到错误凭据。补丁用 get_file_active()/fput() 包裹访问以消除竞态。</p><blockquote><p><strong>学习价值</strong>：提醒学习者：RCU 保护的是 slab 槽位可复用而非对象内容有效，跨对象链式解引用必须显式固定引用。</p></blockquote><h3 id="ea57086ca586-·-patch-v2-nf-0-5-netfilter-pin-file-with-get-file-active-before-reading-f-cred-1" tabindex="-1"><code>ea57086ca586</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-1-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 0/5] netfilter: pin file with get_file_active before reading f_cred</a> <a class="header-anchor" href="#ea57086ca586-·-patch-v2-nf-0-5-netfilter-pin-file-with-get-file-active-before-reading-f-cred-1" aria-label="Permalink to &quot;`ea57086ca586` · [[PATCH v2 nf 0/5] netfilter: pin file with get_file_active before reading f_cred](https://lore.kernel.org/all/20261127001637.1026589-1-tristmd@gmail.com/)&quot;">​</a></h3><p><em>Tristan Madani (<a href="mailto:tristmd@gmail.com" target="_blank" rel="noreferrer">tristmd@gmail.com</a>)｜netdev</em></p><p>本系列修复 netfilter 中五处调用点：它们在 RCU 下通过 sk-&gt;sk_socket-&gt;file 链读取 f_cred 却未固定 file 引用。自 commit 0ede61d8589c 将 file slab 转换为 SLAB_TYPESAFE_BY_RCU 后，file 对象可在宽限期内被释放并重新分配，导致读到复用对象的过期凭据。系列统一采用 get_file_active() 固定、fput() 释放的模式，与已合入的 cls_flow 修复（commit 59cf9e6f48e5a）保持一致。</p><blockquote><p><strong>学习价值</strong>：作为 cover letter，清晰呈现了一个核心 slab 语义变更如何在多个子系统中引发连锁修复，是学习跨子系统回归分析的范本。</p></blockquote><h3 id="a923515486ad-·-patch-net-next-rxrpc-reject-unsecured-calls-to-userspace-services-with-a-minimum-level-1" tabindex="-1"><code>a923515486ad</code> · <a href="https://lore.kernel.org/all/20261126224137.55862-1-bugs@stellman-greene.com/" target="_blank" rel="noreferrer">[PATCH net-next] rxrpc: Reject unsecured calls to userspace services with a minimum level</a> <a class="header-anchor" href="#a923515486ad-·-patch-net-next-rxrpc-reject-unsecured-calls-to-userspace-services-with-a-minimum-level-1" aria-label="Permalink to &quot;`a923515486ad` · [[PATCH net-next] rxrpc: Reject unsecured calls to userspace services with a minimum level](https://lore.kernel.org/all/20261126224137.55862-1-bugs@stellman-greene.com/)&quot;">​</a></h3><p><em>Andrew Stellman (<a href="mailto:bugs@stellman-greene.com" target="_blank" rel="noreferrer">bugs@stellman-greene.com</a>)｜netdev</em></p><p>rxrpc 的 rxrpc_get_incoming_security() 未检查 rx-&gt;min_sec_level，导致用户态服务 socket 即使设置了高于 RXRPC_SECURITY_PLAIN 的最低安全级别，仍会接受安全索引为 RXRPC_SECURITY_NONE 的未加密呼入。补丁在此情况下拒绝未安全呼入，内核 socket（如 kAFS、rxperf）因已设置 RXRPC_SECURITY_ENCRYPT 而不受影响。</p><blockquote><p><strong>学习价值</strong>：展示了协议安全级别检查的边界情况：安全策略校验遗漏在哪个环节引入，以及如何兼顾内核内部使用者的兼容性。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="e714416183b6-·-patch-v3-1-1-docs-filesystems-update-filesystem-type-superblock-and-inode-documentation" tabindex="-1"><code>e714416183b6</code> · <a href="https://lore.kernel.org/all/20261127003236.20196-2-mohamedalibouhaouala@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 1/1] docs: filesystems: update filesystem type, superblock and inode documentation</a> <a class="header-anchor" href="#e714416183b6-·-patch-v3-1-1-docs-filesystems-update-filesystem-type-superblock-and-inode-documentation" aria-label="Permalink to &quot;`e714416183b6` · [[PATCH v3 1/1] docs: filesystems: update filesystem type, superblock and inode documentation](https://lore.kernel.org/all/20261127003236.20196-2-mohamedalibouhaouala@gmail.com/)&quot;">​</a></h3><p><em>mohamedalibouhaouala (<a href="mailto:mohamedalibouhaouala@gmail.com" target="_blank" rel="noreferrer">mohamedalibouhaouala@gmail.com</a>)｜linux-mm</em></p><p>该补丁更新 VFS 文档中 file_system_type、super_operations 和 inode_operations 结构体的说明，补充了 sync_inode_metadata()、remove_bdev()、shutdown()、report_error()、fiemap() 等此前缺失的成员和回调签名，并澄清了 inode 分配/销毁语义、RCU 要求、inode eviction、文件系统冻结及块设备移除处理等内容。</p><blockquote><p><strong>学习价值</strong>：VFS 文档补全是学习 superblock/inode 操作接口的优质一手资料，适合作为阅读 Documentation/filesystems 的配套参考。</p></blockquote><h3 id="_5f2c4c3d765b-·-patch-v3-0-1-docs-filesystems-update-filesystem-type-superblock-and-inode-documentation" tabindex="-1"><code>5f2c4c3d765b</code> · <a href="https://lore.kernel.org/all/20261127003236.20196-1-mohamedalibouhaouala@gmail.com/" target="_blank" rel="noreferrer">[PATCH v3 0/1] docs: filesystems: update filesystem type, superblock and inode documentation</a> <a class="header-anchor" href="#_5f2c4c3d765b-·-patch-v3-0-1-docs-filesystems-update-filesystem-type-superblock-and-inode-documentation" aria-label="Permalink to &quot;`5f2c4c3d765b` · [[PATCH v3 0/1] docs: filesystems: update filesystem type, superblock and inode documentation](https://lore.kernel.org/all/20261127003236.20196-1-mohamedalibouhaouala@gmail.com/)&quot;">​</a></h3><p><em>mohamedalibouhaouala (<a href="mailto:mohamedalibouhaouala@gmail.com" target="_blank" rel="noreferrer">mohamedalibouhaouala@gmail.com</a>)｜linux-mm</em></p><p>v3 版本针对评审意见修正了 file_system_type.list 的初始化描述：该成员是嵌入的 struct hlist_node，零初始化即为未哈希状态，显式初始化可使用 INIT_HLIST_NODE()。补丁还展示了 hlist_node 的结构定义和初始化辅助函数。</p><blockquote><p><strong>学习价值</strong>：通过一个具体评审案例展示了 hlist_node 的语义细节，是理解内核链表实现与文档评审流程的好例子。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_449fd1007c15-·-patch-v8-3-3-drm-panthor-expose-performance-counter-queries-and-ioctls" tabindex="-1"><code>449fd1007c15</code> · <a href="https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-3-6e7db0ec33f5@arm.com/" target="_blank" rel="noreferrer">[PATCH v8 3/3] drm/panthor: Expose performance counter queries and ioctls</a> <a class="header-anchor" href="#_449fd1007c15-·-patch-v8-3-3-drm-panthor-expose-performance-counter-queries-and-ioctls" aria-label="Permalink to &quot;`449fd1007c15` · [[PATCH v8 3/3] drm/panthor: Expose performance counter queries and ioctls](https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-3-6e7db0ec33f5@arm.com/)&quot;">​</a></h3><p><em>Lukas Zapolskas (<a href="mailto:lukas.zapolskas@arm.com" target="_blank" rel="noreferrer">lukas.zapolskas@arm.com</a>)｜rust-for-linux</em></p><p>drm/panthor 驱动补丁系列第三部分，暴露 DEV_QUERY.PERF_INFO 查询和五个性能计数器 session ioctl，并附带 UAPI 文档。同时引入一个基于作用域的 drm_dev_enter()/drm_dev_exit() 包装以保证清理正确性。</p><blockquote><p><strong>学习价值</strong>：适合学习 DRM UAPI ioctl 的设计模式，以及如何用 RAII 风格包装器简化内核中 enter/exit 配对调用的错误处理。</p></blockquote><h3 id="_4522bade3e4f-·-patch-v8-2-3-drm-panthor-implement-performance-counter-firmware-sampling" tabindex="-1"><code>4522bade3e4f</code> · <a href="https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-2-6e7db0ec33f5@arm.com/" target="_blank" rel="noreferrer">[PATCH v8 2/3] drm/panthor: Implement performance counter firmware sampling</a> <a class="header-anchor" href="#_4522bade3e4f-·-patch-v8-2-3-drm-panthor-implement-performance-counter-firmware-sampling" aria-label="Permalink to &quot;`4522bade3e4f` · [[PATCH v8 2/3] drm/panthor: Implement performance counter firmware sampling](https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-2-6e7db0ec33f5@arm.com/)&quot;">​</a></h3><p><em>Lukas Zapolskas (<a href="mailto:lukas.zapolskas@arm.com" target="_blank" rel="noreferrer">lukas.zapolskas@arm.com</a>)｜rust-for-linux</em></p><p>drm/panthor 性能计数器系列的第二部分，实现 panthor_perf 模块：聚合来自用户态的计数器请求并与固件接口交互，防止用户 session 覆盖全局配置。收到 GLB_ACK 寄存器相关中断后，根据 insert/extract 索引将硬件 32 位计数器零扩展为 64 位并累积到内部缓冲区。</p><blockquote><p><strong>学习价值</strong>：展示了 GPU 驱动中固件接口交互、中断驱动采样与缓冲区索引管理的完整设计，对学习驱动子系统架构很有参考价值。</p></blockquote><h3 id="_922c760147ab-·-patch-v8-0-3-drm-panthor-performance-counter-implementation-with-single-manual-client-support" tabindex="-1"><code>922c760147ab</code> · <a href="https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-0-6e7db0ec33f5@arm.com/" target="_blank" rel="noreferrer">[PATCH v8 0/3] drm/panthor: Performance counter implementation with single manual client support</a> <a class="header-anchor" href="#_922c760147ab-·-patch-v8-0-3-drm-panthor-performance-counter-implementation-with-single-manual-client-support" aria-label="Permalink to &quot;`922c760147ab` · [[PATCH v8 0/3] drm/panthor: Performance counter implementation with single manual client support](https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-0-6e7db0ec33f5@arm.com/)&quot;">​</a></h3><p><em>Lukas Zapolskas (<a href="mailto:lukas.zapolskas@arm.com" target="_blank" rel="noreferrer">lukas.zapolskas@arm.com</a>)｜rust-for-linux</em></p><p>drm/panthor 性能计数器实现的 cover letter，作为 Adrián Larumbe 早期系列的后续，裁剪掉未实际填充的 uAPI 特性，仅保留初始实现所需功能。Mali 性能计数器通过全局固件接口控制，采样缓冲区中每个 block 实例包含 64 或 128 个 32 位计数器，各 block 类型有独立的 32 位使能掩码。</p><blockquote><p><strong>学习价值</strong>：体现了 uAPI 演进中&#39;只暴露已实现功能&#39;的原则，以及 GPU 硬件计数器体系（block、enable mask）的基础知识。</p></blockquote><h3 id="b5ab173b658f-·-patch-v8-1-3-drm-panthor-add-perf-setup-and-session-management" tabindex="-1"><code>b5ab173b658f</code> · <a href="https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-1-6e7db0ec33f5@arm.com/" target="_blank" rel="noreferrer">[PATCH v8 1/3] drm/panthor: Add perf setup and session management</a> <a class="header-anchor" href="#b5ab173b658f-·-patch-v8-1-3-drm-panthor-add-perf-setup-and-session-management" aria-label="Permalink to &quot;`b5ab173b658f` · [[PATCH v8 1/3] drm/panthor: Add perf setup and session management](https://lore.kernel.org/all/20261126-panthor-performance-counters-v8-1-6e7db0ec33f5@arm.com/)&quot;">​</a></h3><p><em>Lukas Zapolskas (<a href="mailto:lukas.zapolskas@arm.com" target="_blank" rel="noreferrer">lukas.zapolskas@arm.com</a>)｜rust-for-linux</em></p><p>系列第一部分，添加 panthor_perf 子系统的初始化与拔出代码及用户 session 管理。提供五个原语操作：SESSION_CREATE 创建带静态计数器配置的 session、SESSION_START 激活采样、SESSION_SAMPLE 请求采样并通过 eventfd 通知完成、SESSION_STOP 停止采样、SESSION_DESTROY 释放 session。</p><blockquote><p><strong>学习价值</strong>：是学习如何设计状态机式 session 生命周期管理（create/start/sample/stop/destroy）和 eventfd 异步通知机制的好例子。</p></blockquote><h3 id="_2f779400e6d5-·-patch-rust-drm-gpuvm-store-the-driver-data-in-uniquerefgpuvm" tabindex="-1"><code>2f779400e6d5</code> · <a href="https://lore.kernel.org/all/20261126-gpuvm-data-in-handle-v1-1-47b1e9928f20@collabora.com/" target="_blank" rel="noreferrer">[PATCH] rust: drm: gpuvm: store the driver data in UniqueRefGpuVm</a> <a class="header-anchor" href="#_2f779400e6d5-·-patch-rust-drm-gpuvm-store-the-driver-data-in-uniquerefgpuvm" aria-label="Permalink to &quot;`2f779400e6d5` · [[PATCH] rust: drm: gpuvm: store the driver data in UniqueRefGpuVm](https://lore.kernel.org/all/20261126-gpuvm-data-in-handle-v1-1-47b1e9928f20@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>Rust DRM gpuvm 抽象的改进：原先 GpuVm&lt;T&gt; 将驱动数据放在引用计数分配内的 UnsafeCell&lt;T&gt; 中，由 UniqueRefGpuVm 通过 unsafe 访问器访问。由于只有 UniqueRefGpuVm 访问该数据，补丁将数据移入 UniqueRefGpuVm，使 data()/data_mut() 变为普通字段访问；GpuVm&lt;T&gt; 保留 PhantomData&lt;*mut T&gt; 以维持对 T 的不变性，数据随 UniqueRefGpuVm 而非最后一个引用释放。</p><blockquote><p><strong>学习价值</strong>：深入讲解 Rust 泛型型变（variance）、PhantomData 与 UnsafeCell 的取舍，是理解内核 Rust 抽象中所有权与生命周期设计的高级案例。</p></blockquote><h3 id="_43f5b2b68131-·-patch-2-4-drm-tyr-use-the-conversion-derives-for-the-mmu-as-control-enums" tabindex="-1"><code>43f5b2b68131</code> · <a href="https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-2-a487b0e1bee3@collabora.com/" target="_blank" rel="noreferrer">[PATCH 2/4] drm/tyr: use the conversion derives for the MMU_AS_CONTROL enums</a> <a class="header-anchor" href="#_43f5b2b68131-·-patch-2-4-drm-tyr-use-the-conversion-derives-for-the-mmu-as-control-enums" aria-label="Permalink to &quot;`43f5b2b68131` · [[PATCH 2/4] drm/tyr: use the conversion derives for the MMU_AS_CONTROL enums](https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-2-a487b0e1bee3@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 Tyr DRM 驱动中 MMU_AS_CONTROL 枚举与 <code>Bounded</code> 之间手写的转换改为使用 conversion derives 自动派生，消除了 10 处 <code>as</code> 强制转换。<code>as</code> 转换会静默丢弃超出目标类型范围的位，且无法从代码中看出这种风险。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核驱动中如何用 derive 宏替代手写转换以消除 <code>as</code> cast 的隐患，是学习内核 Rust 安全类型转换实践的好例子。</p></blockquote><h3 id="_2967879d0344-·-patch-1-4-drm-tyr-use-the-conversion-derives-for-the-gpu-control-enums" tabindex="-1"><code>2967879d0344</code> · <a href="https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-1-a487b0e1bee3@collabora.com/" target="_blank" rel="noreferrer">[PATCH 1/4] drm/tyr: use the conversion derives for the GPU_CONTROL enums</a> <a class="header-anchor" href="#_2967879d0344-·-patch-1-4-drm-tyr-use-the-conversion-derives-for-the-gpu-control-enums" aria-label="Permalink to &quot;`2967879d0344` · [[PATCH 1/4] drm/tyr: use the conversion derives for the GPU_CONTROL enums](https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-1-a487b0e1bee3@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 Tyr DRM 驱动中 GPU_CONTROL 枚举与 <code>Bounded</code> 之间的手写转换改为 conversion derives 派生实现，移除了 8 处枚举转整数的 <code>as</code> cast。这是 Tyr 驱动减少 <code>as</code> cast 数量的系列工作的一部分，无功能性变更。</p><blockquote><p><strong>学习价值</strong>：与系列其他补丁一起展示了 Rust 内核代码中用类型安全转换替代 <code>as</code> cast 的系统性重构思路。</p></blockquote><h3 id="_3b6d097e6ecf-·-patch-4-4-drm-tyr-use-the-tryfrom-derive-for-entrytype" tabindex="-1"><code>3b6d097e6ecf</code> · <a href="https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-4-a487b0e1bee3@collabora.com/" target="_blank" rel="noreferrer">[PATCH 4/4] drm/tyr: use the <code>TryFrom</code> derive for <code>EntryType</code></a> <a class="header-anchor" href="#_3b6d097e6ecf-·-patch-4-4-drm-tyr-use-the-tryfrom-derive-for-entrytype" aria-label="Permalink to &quot;`3b6d097e6ecf` · [[PATCH 4/4] drm/tyr: use the `TryFrom` derive for `EntryType`](https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-4-a487b0e1bee3@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p><code>EntryType</code> 是 Tyr 驱动中最后一个手写实现从 <code>Bounded</code> 转换的枚举，该补丁将其改为使用 <code>TryFrom</code> derive，使所有枚举统一采用 conversion derives。涉及 fw/parser.rs 中固件解析代码，无功能性变更。</p><blockquote><p><strong>学习价值</strong>：体现了 Rust 内核代码追求一致性和最小化手写样板代码的风格，对理解 derive 宏在内核中的应用有参考价值。</p></blockquote><h3 id="_5a5ef907ccd0-·-patch-3-4-drm-tyr-use-the-conversion-derives-for-cachemode" tabindex="-1"><code>5a5ef907ccd0</code> · <a href="https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-3-a487b0e1bee3@collabora.com/" target="_blank" rel="noreferrer">[PATCH 3/4] drm/tyr: use the conversion derives for <code>CacheMode</code></a> <a class="header-anchor" href="#_5a5ef907ccd0-·-patch-3-4-drm-tyr-use-the-conversion-derives-for-cachemode" aria-label="Permalink to &quot;`5a5ef907ccd0` · [[PATCH 3/4] drm/tyr: use the conversion derives for `CacheMode`](https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-3-a487b0e1bee3@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 Tyr 驱动中 <code>CacheMode</code> 枚举与 <code>Bounded</code> 之间的手写转换改为 conversion derives 派生，移除了将 <code>CacheMode</code> 转为整数的 <code>as</code> cast。属于减少 Tyr 中 <code>as</code> cast 的系列补丁之一，无功能性变更。</p><blockquote><p><strong>学习价值</strong>：进一步示范了用 <code>TryFrom</code>/<code>From</code>/<code>Into</code> derives 处理枚举与整数互转的安全模式。</p></blockquote><h3 id="ca37605c2cf8-·-patch-0-4-drm-tyr-use-the-conversion-derives-for-the-enums" tabindex="-1"><code>ca37605c2cf8</code> · <a href="https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-0-a487b0e1bee3@collabora.com/" target="_blank" rel="noreferrer">[PATCH 0/4] drm/tyr: use the conversion derives for the enums</a> <a class="header-anchor" href="#ca37605c2cf8-·-patch-0-4-drm-tyr-use-the-conversion-derives-for-the-enums" aria-label="Permalink to &quot;`ca37605c2cf8` · [[PATCH 0/4] drm/tyr: use the conversion derives for the enums](https://lore.kernel.org/all/20261126-tyr-enum-derives-v1-0-a487b0e1bee3@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>本系列补丁（共 4 个）将 Tyr DRM 驱动中剩余 19 处枚举转整数的 <code>as</code> cast 全部消除，方法是使用 Kaiqi 的 &quot;conversion derives and exhaustive From support&quot; 系列补丁中的 <code>TryFrom</code>、<code>From</code> 和 <code>Into</code> derives 来派生枚举与 <code>Bounded</code> 之间的转换。基于 drm-rust-next 分支，依赖前置的 <code>as</code> cast 系列和 conversion derives 系列补丁。</p><blockquote><p><strong>学习价值</strong>：作为 cover letter 展示了内核 Rust 补丁系列的依赖关系组织方式，以及社区协作中补丁分层与评审的流程，对学习内核开发工作流很有帮助。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="_36f924db1c95-·-linux-7-4-delivers-some-performance-gains-for-intel-panther-lake-s-arc-b390-graphics" tabindex="-1"><code>36f924db1c95</code> · <a href="https://www.phoronix.com/news/Linux-7.4-Arc-B390-Performance" target="_blank" rel="noreferrer">Linux 7.4 Delivers Some Performance Gains For Intel Panther Lake&#39;s Arc B390 Graphics</a> <a class="header-anchor" href="#_36f924db1c95-·-linux-7-4-delivers-some-performance-gains-for-intel-panther-lake-s-arc-b390-graphics" aria-label="Permalink to &quot;`36f924db1c95` · [Linux 7.4 Delivers Some Performance Gains For Intel Panther Lake&#39;s Arc B390 Graphics](https://www.phoronix.com/news/Linux-7.4-Arc-B390-Performance)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>在搭载 Intel Core Ultra Series 3 &quot;Panther Lake&quot; 的 Dell XPS 14 上测试显示，从 Ubuntu 26.04 LTS 升级到 26.10 可带来性能提升，而使用开发中的 Linux 7.4 内核则对 Arc B390 集成 Xe3 图形有进一步优化。</p><blockquote><p><strong>学习价值</strong>：可作为观察新内核版本对 Intel 新硬件（Xe3 图形）驱动性能持续优化的实例参考。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_937813fb13fa-·-next-20261126-linux-next" tabindex="-1"><code>937813fb13fa</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261126-2026-11-26" target="_blank" rel="noreferrer">next-20261126: linux-next</a> <a class="header-anchor" href="#_937813fb13fa-·-next-20261126-linux-next" aria-label="Permalink to &quot;`937813fb13fa` · [next-20261126: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261126-2026-11-26)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 26 日发布 next-20261126 版本。linux-next 是汇集各子系统树待合并补丁的集成测试树，供社区在进入主线前进行构建与测试验证。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 版本有助于学习者了解即将进入主线的特性动态，是观察内核开发节奏的日常窗口。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_7e2a8993dd8a-·-it-looks-like-ai-agent-skills-will-be-submitted-for-linux-7-5-1" tabindex="-1"><code>7e2a8993dd8a</code> · <a href="https://www.phoronix.com/news/Linux-AI-Agent-Skills-Ready" target="_blank" rel="noreferrer">It Looks Like AI Agent Skills Will Be Submitted For Linux 7.5</a> <a class="header-anchor" href="#_7e2a8993dd8a-·-it-looks-like-ai-agent-skills-will-be-submitted-for-linux-7-5-1" aria-label="Permalink to &quot;`7e2a8993dd8a` · [It Looks Like AI Agent Skills Will Be Submitted For Linux 7.5](https://www.phoronix.com/news/Linux-AI-Agent-Skills-Ready)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>在即将于 12 月底开启的 Linux 7.5 merge window 中，社区计划提交 AI agent skills 相关内容，即在内核树内添加文档，用于指导 AI agent 理解和参与内核开发流程。这标志着 AI 辅助开发正被正式纳入内核工作流。</p><blockquote><p><strong>学习价值</strong>：了解内核社区如何主动拥抱 AI 辅助开发，是观察内核开发流程演进的重要窗口。</p></blockquote><h3 id="_2fc70ff2b0ba-·-amid-all-the-ai-generated-patches-bug-reports-linux-gains-another-network-maintainer-1" tabindex="-1"><code>2fc70ff2b0ba</code> · <a href="https://www.phoronix.com/news/Linux-Another-Net-Maintainer" target="_blank" rel="noreferrer">Amid All The AI Generated Patches &amp; Bug Reports, Linux Gains Another Network Maintainer</a> <a class="header-anchor" href="#_2fc70ff2b0ba-·-amid-all-the-ai-generated-patches-bug-reports-linux-gains-another-network-maintainer-1" aria-label="Permalink to &quot;`2fc70ff2b0ba` · [Amid All The AI Generated Patches &amp; Bug Reports, Linux Gains Another Network Maintainer](https://www.phoronix.com/news/Linux-Another-Net-Maintainer)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>由于过去一年大量 AI/LLM 生成的 bug report 和 patch 让 Linux networking 维护者不堪重负，甚至导致部分修复被推迟到下个版本、部分老旧网络代码被直接移除。作为应对，又一位开发者被提升为 networking 子系统的额外 maintainer。</p><blockquote><p><strong>学习价值</strong>：展示了 AI 生成内容对上游内核维护生态的实际冲击，以及社区通过扩充 maintainer 队伍的应对策略。</p></blockquote><h3 id="_85b5e1c13bb6-·-ubuntu-27-04-snapshot-1-released-for-testing" tabindex="-1"><code>85b5e1c13bb6</code> · <a href="https://www.phoronix.com/news/Ubuntu-27.04-Snapshot-1" target="_blank" rel="noreferrer">Ubuntu 27.04 Snapshot 1 Released For Testing</a> <a class="header-anchor" href="#_85b5e1c13bb6-·-ubuntu-27-04-snapshot-1-released-for-testing" aria-label="Permalink to &quot;`85b5e1c13bb6` · [Ubuntu 27.04 Snapshot 1 Released For Testing](https://www.phoronix.com/news/Ubuntu-27.04-Snapshot-1)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Ubuntu 27.04（代号 Tenacious）的首个 Snapshot 1 测试镜像发布，是通往正式版的第一块垫脚石。这是面向测试者的早期构建，供感恩节假期有余力的用户尝鲜。</p><blockquote><p><strong>学习价值</strong>：与内核本身关系不大，仅可作为发行版时间线参考，对内核学习者价值有限。</p></blockquote><h3 id="_051e1944f263-·-dxvk-3-2-released-with-present-timing-support" tabindex="-1"><code>051e1944f263</code> · <a href="https://www.phoronix.com/news/DXVK-3.2-Released" target="_blank" rel="noreferrer">DXVK 3.2 Released With Present Timing Support</a> <a class="header-anchor" href="#_051e1944f263-·-dxvk-3-2-released-with-present-timing-support" aria-label="Permalink to &quot;`051e1944f263` · [DXVK 3.2 Released With Present Timing Support](https://www.phoronix.com/news/DXVK-3.2-Released)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>DXVK 3.2 发布，这是 Valve Steam Play（Proton）所使用的基于 Vulkan 的 Direct3D 8–11 实现的最新特性版本，新增 present timing 支持。</p><blockquote><p><strong>学习价值</strong>：属于用户态图形翻译层项目，与内核开发关联较弱，对内核学习者价值有限。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>0e89198a0bf1</code> · <a href="https://lore.kernel.org/all/20261126-skb_refcount_overflow-v2-0-a6f600a5634a@kernel.org/" target="_blank" rel="noreferrer">[PATCH net v2 0/4] net: skbuff: limit pagecache folio refcount</a></li><li><code>ea57086ca586</code> · <a href="https://lore.kernel.org/all/20261127001637.1026589-1-tristmd@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 nf 0/5] netfilter: pin file with get_file_active before reading f_cred</a></li><li><code>a923515486ad</code> · <a href="https://lore.kernel.org/all/20261126224137.55862-1-bugs@stellman-greene.com/" target="_blank" rel="noreferrer">[PATCH net-next] rxrpc: Reject unsecured calls to userspace services with a minimum level</a></li></ul>',180)])])}const h=r(n,[["render",l]]);export{p as __pageData,h as default};
